WITH fixes(slug,pos,why) AS (VALUES ('administrativo-poder-de-policia-ciclo-prescricao',4,'Correto. O art. 78 do CTN define poder de polícia como atividade administrativa que limita ou disciplina direitos e liberdades em razão do interesse público.'),
('administrativo-poder-de-policia-ciclo-prescricao',5,'Correto. Segurança e higiene são interesses expressamente mencionados no art. 78 do CTN como fundamentos do exercício do poder de polícia.'),
('administrativo-poder-de-policia-ciclo-prescricao',6,'Correto. O art. 78 do CTN inclui a disciplina da produção e do mercado entre os interesses protegidos pelo poder de polícia.'),
('administrativo-poder-de-policia-ciclo-prescricao',7,'Correto. O art. 78 do CTN contempla atividades econômicas dependentes de concessão ou autorização do poder público.'),
('administrativo-poder-de-policia-ciclo-prescricao',13,'Correto. A tranquilidade pública é um dos interesses mencionados no art. 78 do CTN para justificar a atuação de polícia administrativa.'),
('administrativo-poder-de-policia-ciclo-prescricao',14,'Correto. A proteção dos costumes está expressamente incluída no art. 78 do CTN entre os interesses ligados ao poder de polícia.'),
('administrativo-poder-de-policia-ciclo-prescricao',15,'Correto. O art. 78 do CTN menciona respeito à propriedade e aos direitos individuais ou coletivos no conceito legal de poder de polícia.'),
('administrativo-poder-de-policia-ciclo-prescricao',16,'Correto. O art. 77 do CTN admite taxa em razão do exercício regular do poder de polícia, respeitados os requisitos legais.'),
('administrativo-poder-de-policia-ciclo-prescricao',18,'Correto. O caput do art. 78 do CTN descreve o poder de polícia como atividade da administração pública que limita ou disciplina direitos.'),
('administrativo-poder-de-policia-ciclo-prescricao',19,'Correto. O art. 78 do CTN inclui a ordem pública entre os interesses protegidos pela atividade de polícia administrativa.'),
('administrativo-processo-administrativo-lei-9784',3,'Correto. A Lei 14.210/2021 inseriu na Lei 9.784/1999 os arts. 49-A a 49-G, disciplinando a decisão coordenada.'),
('administrativo-processo-administrativo-lei-9784',14,'Correto. O art. 13, II, da Lei 9.784/1999 impede delegar a decisão de recursos administrativos.'),
('administrativo-processo-administrativo-lei-9784',16,'Correto. Pelo art. 18, I, da Lei 9.784/1999, quem tem interesse direto ou indireto na matéria está impedido de atuar no processo.'),
('administrativo-processo-administrativo-lei-9784',17,'Correto. O art. 20 da Lei 9.784/1999 admite arguição de suspeição de autoridade ou servidor que tenha amizade íntima com interessado.'),
('administrativo-improbidade-lei-8429-reforma-14230',5,'Correto. O art. 1º da Lei 8.429/1992 protege a probidade na organização do Estado e no exercício de suas funções.'),
('administrativo-improbidade-lei-8429-reforma-14230',16,'Correto. O art. 12 da Lei 8.429/1992 prevê perda da função pública em hipóteses legalmente delimitadas, com observância dos requisitos e da proporcionalidade.')), rebuilt AS (SELECT sm.id,jsonb_agg(CASE WHEN f.pos IS NOT NULL AND length(trim(coalesce(e.value->>'why','')))<25 THEN jsonb_set(e.value,'{why}',to_jsonb(f.why)) ELSE e.value END ORDER BY e.ordinality) quiz FROM study_materials sm CROSS JOIN LATERAL jsonb_array_elements(sm.quiz) WITH ORDINALITY e(value,ordinality) LEFT JOIN fixes f ON f.slug=sm.slug AND f.pos=e.ordinality WHERE sm.slug IN (SELECT DISTINCT slug FROM fixes) GROUP BY sm.id) UPDATE study_materials sm SET quiz=r.quiz,updated_at=now() FROM rebuilt r WHERE sm.id=r.id;